import React, { useEffect, useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { io } from "socket.io-client";

const socket = io("https://chat-app-backend-4f2r.onrender.com");

const Friends = () => {
  const navigate = useNavigate();
  const [search, setSearch] = useState("");
  const [incomingRequests, setIncomingRequests] = useState([]);
  const [allUsers, setAllUsers] = useState([]);
  const [sentRequests, setSentRequests] = useState([]);
  const [friendsList, setFriendsList] = useState([]);

  const storedUser = localStorage.getItem("user");
  const currentUser = storedUser ? JSON.parse(storedUser) : null;
  const userId = currentUser?.id;

  // =========================
  // FETCH FUNCTIONS
  // =========================

  const fetchIncomingRequests = async () => {
    try {
      const res = await axios.get(
        `https://chat-app-backend-4f2r.onrender.com/api/friends/incoming/${userId}`
      );
      setIncomingRequests(res.data || []);
    } catch (err) {
      console.log("Incoming Request Error:", err);
    }
  };

  const fetchFriends = async () => {
    try {
      const res = await axios.get(
        `https://chat-app-backend-4f2r.onrender.com/api/friends/${userId}`
      );
      setFriendsList(res.data || []);
    } catch (err) {
      console.log("Friends Fetch Error:", err);
    }
  };

  const fetchUsers = async () => {
    try {
      const res = await axios.get("https://chat-app-backend-4f2r.onrender.com/api/users");
      setAllUsers(res.data || []);
    } catch (err) {
      console.log("Users Fetch Error:", err);
    }
  };

  // =========================
  // ACTIONS
  // =========================

  const acceptRequest = async (requestId, senderId) => {
    try {
      await axios.post("https://chat-app-backend-4f2r.onrender.com/api/friends/accept", {
        request_id: requestId,
      });

      // 🔥 Notify sender in real-time
      socket.emit("friendRequestAccepted", { receiverId: senderId });

      fetchIncomingRequests();
      fetchFriends();
    } catch (err) {
      console.log("Accept Error:", err);
    }
  };

  const rejectRequest = async (requestId) => {
    try {
      await axios.post("https://chat-app-backend-4f2r.onrender.com/api/friends/reject", {
        request_id: requestId,
      });

      fetchIncomingRequests();
    } catch (err) {
      console.log("Reject Error:", err);
    }
  };

  const sendRequest = async (receiverId) => {
    try {
      await axios.post("https://chat-app-backend-4f2r.onrender.com/api/friends/send", {
        sender_id: userId,
        receiver_id: receiverId,
        sender_name: currentUser.name,
      });

      // 🔥 Real-time notify receiver
      socket.emit("sendFriendRequest", { receiverId });

      setSentRequests((prev) => [...prev, receiverId]);
    } catch (err) {
      console.log("Send Request Error:", err);
    }
  };

  // =========================
  // SOCKET SETUP
  // =========================

  useEffect(() => {
    if (!userId) return;

    // Join online users map
    socket.emit("addUser", userId);

    fetchIncomingRequests();
    fetchUsers();
    fetchFriends();

    // 🔥 Listen for new friend request
    socket.on("newFriendRequest", () => {
      fetchIncomingRequests();
    });

    // 🔥 Listen for friend accepted
    socket.on("friendAdded", () => {
      fetchFriends();
    });

    return () => {
      socket.off("newFriendRequest");
      socket.off("friendAdded");
    };
  }, [userId]);

  // =========================
  // FILTER USERS
  // =========================

  const filteredUsers = allUsers.filter((user) =>
    user.name.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div style={{ padding: "20px" }}>
      <button onClick={() => navigate("/chat")}>⬅ Back to Chat</button>

      {/* SEARCH */}
      <div style={{ marginBottom: "20px" }}>
        <input
          type="text"
          placeholder="Search users to add friends..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          style={{
            width: "100%",
            padding: "10px",
            borderRadius: "8px",
            border: "1px solid #ccc",
            fontSize: "14px",
          }}
        />
      </div>

      <h2>Incoming Friend Requests 📩</h2>

      {incomingRequests.length === 0 ? (
        <p>No incoming requests</p>
      ) : (
        incomingRequests.map((req) => (
          <div
            key={req.id}
            style={{
              border: "1px solid #ccc",
              padding: "10px",
              marginBottom: "10px",
              borderRadius: "8px",
            }}
          >
            <strong>{req.sender_name}</strong>

            <div style={{ marginTop: "8px" }}>
              <button
                onClick={() => acceptRequest(req.id, req.sender_id)}
                style={{
                  background: "green",
                  color: "white",
                  marginRight: "10px",
                  padding: "6px 12px",
                  border: "none",
                  borderRadius: "6px",
                  cursor: "pointer",
                }}
              >
                Accept
              </button>

              <button
                onClick={() => rejectRequest(req.id)}
                style={{
                  background: "red",
                  color: "white",
                  padding: "6px 12px",
                  border: "none",
                  borderRadius: "6px",
                  cursor: "pointer",
                }}
              >
                Reject
              </button>
            </div>
          </div>
        ))
      )}

      <h2>Add Friends 👥</h2>

      {filteredUsers
        .filter((u) => u.id !== userId)
        .filter(
          (u) =>
            !friendsList.some((friend) => friend.id === u.id) &&
            !sentRequests.includes(u.id)
        )
        .map((user) => (
          <div
            key={user.id}
            style={{
              border: "1px solid #ddd",
              padding: "10px",
              marginBottom: "8px",
              borderRadius: "6px",
              display: "flex",
              justifyContent: "space-between",
            }}
          >
            <span>{user.name}</span>

            <button
              onClick={() => sendRequest(user.id)}
              disabled={sentRequests.includes(user.id)}
              style={{
                background: sentRequests.includes(user.id)
                  ? "gray"
                  : "blue",
                color: "white",
                border: "none",
                padding: "6px 12px",
                borderRadius: "6px",
                cursor: sentRequests.includes(user.id)
                  ? "not-allowed"
                  : "pointer",
              }}
            >
              {sentRequests.includes(user.id)
                ? "Request Sent"
                : "Add Friend"}
            </button>
          </div>
        ))}
    </div>
  );
};

export default Friends;