import CryptoJS from "crypto-js";

// 🔐 Secret Key (later you can move to .env)
const SECRET_KEY = "chat_app_e2ee_secret_2026";

// Encrypt message before sending
export const encryptMessage = (message) => {
  try {
    if (!message) return "";
    return CryptoJS.AES.encrypt(message, SECRET_KEY).toString();
  } catch (error) {
    console.log("Encryption Error:", error);
    return message; // fallback (never break chat)
  }
};

// Decrypt message when displaying
export const decryptMessage = (cipherText) => {
  try {
    if (!cipherText) return "";

    const bytes = CryptoJS.AES.decrypt(cipherText, SECRET_KEY);
    const decrypted = bytes.toString(CryptoJS.enc.Utf8);

    // If decryption fails, show original text (for old messages)
    return decrypted || cipherText;
  } catch (error) {
    console.log("Decryption Error:", error);
    return cipherText;
  }
};