import React, { useEffect, useRef, useState } from "react";
import { io } from "socket.io-client";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { encryptMessage, decryptMessage } from "../utils/encryption";

// 🔌 Backend socket (KEEP PORT 5000)
const socket = io("https://chat-app-backend-4f2r.onrender.com");

const Chat = () => {
  const navigate = useNavigate();
  const typingTimeoutRef = useRef(null);

  // 🧠 STATES (ALL YOUR FEATURES KEPT)
  const [incomingCount, setIncomingCount] = useState(0);
  const [users, setUsers] = useState([]);
  const [friends, setFriends] = useState([]);
  const [onlineUsers, setOnlineUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [message, setMessage] = useState("");
  const [isTyping, setIsTyping] = useState(false);
  const [unreadCounts, setUnreadCounts] = useState({});

  // 🔐 Logged user
  const storedUser = localStorage.getItem("user");
  const currentUser = storedUser ? JSON.parse(storedUser) : null;
  const senderId =
    currentUser?.id || currentUser?._id || currentUser?.user?.id;

  // 🔴 LOGOUT (FIXED - instant redirect)
const logout = () => {
  socket.disconnect();
  localStorage.clear();
  window.location.href = "/";
};

  // 👥 Fetch all users (needed to map friend IDs to names)
  const fetchUsers = async () => {
    try {
      const res = await axios.get("https://chat-app-backend-4f2r.onrender.com/api/users");
      setUsers(res.data || []);
    } catch (err) {
      console.log("Fetch Users Error:", err);
    }
  };
const fetchIncomingCount = async () => {
  try {
    const res = await axios.get(
      `https://chat-app-backend-4f2r.onrender.com/api/friends/incoming/${currentUser.id}`
    );
    setIncomingCount(res.data.length || 0);
  } catch (err) {
    console.log("Incoming Count Error:", err);
  }
};
  // 🤝 Fetch friends list
  const fetchFriends = async () => {
    try {
      const res = await axios.get(
        `https://chat-app-backend-4f2r.onrender.com/api/friends/${senderId}`
      );
      setFriends(res.data || []);
    } catch (err) {
      console.log("Fetch Friends Error:", err);
    }
  };
  const formatTime = (timestamp) => {
  const date = new Date(timestamp);
  return date.toLocaleTimeString([], {
    hour: "2-digit",
    minute: "2-digit",
  });
};

  // 📜 Fetch chat history
  const fetchMessages = async (receiverId) => {
    try {
      const res = await axios.get(
        `https://chat-app-backend-4f2r.onrender.com/api/messages/history?sender_id=${senderId}&receiver_id=${receiverId}`
      );
      setMessages(res.data || []);
    } catch (err) {
      console.log("Fetch Messages Error:", err);
    }
  };
  // 🧠 Extract friend user IDs (IMPORTANT LOGIC)
  const friendUserIds = friends.map((f) =>
    String(f.sender_id) === String(senderId)
      ? String(f.receiver_id)
      : String(f.sender_id)
  );

  // 👥 ONLY FRIENDS IN SIDEBAR (YOUR REQUIREMENT)
  const friendUsers = users.filter((u) =>
    friendUserIds.includes(String(u.id))
  );
useEffect(() => {
  if (!selectedUser || !senderId) return;

  const interval = setInterval(async () => {
    try {
      const res = await axios.get(
        `https://chat-app-backend-4f2r.onrender.com/api/messages/history?sender_id=${senderId}&receiver_id=${selectedUser.id}`
      );

      setMessages((prev) => {
        const newMessages = res.data || [];

        // Prevent duplicates
        if (JSON.stringify(prev) !== JSON.stringify(newMessages)) {
          return newMessages;
        }

        return prev;
      });
    } catch (err) {
      console.log("Auto refresh error:", err);
    }
  }, 2000); // 🔥 every 2 seconds

  return () => clearInterval(interval);
}, [selectedUser, senderId]);
useEffect(() => {
  const storedUser = localStorage.getItem("user");

  if (!storedUser) {
    navigate("/", { replace: true });
  }
}, []);
  // 🔥 SOCKET + INITIAL LOAD
  useEffect(() => {
    if (!senderId) {
      navigate("/", { replace: true });
      return;
    }
    

    // 🟢 Register online user
    socket.emit("addUser", String(senderId));

    // Load data
    fetchUsers();
    fetchFriends();
    fetchIncomingCount();
    // 🟢 Online users listener
    socket.on("getOnlineUsers", (ids) => {
      setOnlineUsers(ids.map((id) => String(id)));
    });

    // 💬 Receive messages (Realtime + Unread)
    socket.on("receivePrivateMessage", (data) => {
      const sender = String(data.sender_id);

      if (selectedUser && String(selectedUser.id) === sender) {
        setMessages((prev) => [...prev, data]);

        // 👀 Auto mark as seen
        socket.emit("markSeen", {
          sender_id: data.sender_id,
        });
      } else {
        // 🔔 Unread badge
        setUnreadCounts((prev) => ({
          ...prev,
          [sender]: (prev[sender] || 0) + 1,
        }));
      }
    });

    // ✓ Delivered
    socket.on("messageDelivered", ({ message_id }) => {
      setMessages((prev) =>
        prev.map((msg) =>
          msg.temp_id === message_id
            ? { ...msg, status: "delivered" }
            : msg
        )
      );
    });

    // 👀 Seen ✓✓ (blue)
    socket.on("messageSeen", () => {
      setMessages((prev) =>
        prev.map((msg) =>
          String(msg.sender_id) === String(senderId)
            ? { ...msg, status: "seen" }
            : msg
        )
      );
    });

    // ⌨️ Typing indicator
    socket.on("showTyping", ({ sender_id }) => {
      if (
        selectedUser &&
        String(sender_id) === String(selectedUser.id)
      ) {
        setIsTyping(true);
      }
    });

    socket.on("hideTyping", () => {
      setIsTyping(false);
    });

    return () => {
      socket.off("getOnlineUsers");
      socket.off("receivePrivateMessage");
      socket.off("messageDelivered");
      socket.off("messageSeen");
      socket.off("showTyping");
      socket.off("hideTyping");
    };
  }, [senderId, selectedUser, navigate]);

  // 📤 SEND MESSAGE (E2EE + TICKS SUPPORT)
  const sendMessage = async () => {
    if (!message.trim() || !selectedUser) return;

    const tempId = Date.now().toString();
    const encryptedText = encryptMessage(message);

    const msgData = {
      temp_id: tempId,
      sender_id: String(senderId),
      receiver_id: String(selectedUser.id),
      message: encryptedText,
      status: "sent", // ✓
    };

    // Instant UI update (green bubble)
    setMessages((prev) => [...prev, msgData]);

    // Realtime socket send
    socket.emit("sendPrivateMessage", msgData);

    // Save to DB (unchanged backend)
    try {
      await axios.post(
        "https://chat-app-backend-4f2r.onrender.com/api/messages/save",
        msgData
      );
    } catch (err) {
      console.log("Save Message Error:", err);
    }

    // Stop typing event
    socket.emit("stopTyping", {
      receiver_id: String(selectedUser.id),
    });

    setMessage("");
  };

  // ⌨️ Typing handler (no flicker)
  const handleTyping = (e) => {
    setMessage(e.target.value);

    if (!selectedUser) return;

    socket.emit("typing", {
      sender_id: String(senderId),
      receiver_id: String(selectedUser.id),
    });

    if (typingTimeoutRef.current) {
      clearTimeout(typingTimeoutRef.current);
    }

    typingTimeoutRef.current = setTimeout(() => {
      socket.emit("stopTyping", {
        receiver_id: String(selectedUser.id),
      });
    }, 1500);
  };

  return (
    <div style={{ display: "flex", height: "100vh" }}>
      {/* 🟦 SIDEBAR (FRIENDS ONLY) */}
      <div
        style={{
          width: "300px",
          borderRight: "1px solid #ccc",
          padding: "15px",
          background: "#f4f6f9",
        }}
      >
        {/* HEADER */}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            marginBottom: "12px",
            alignItems: "center",
          }}
        >
          <h3>Friends 👥</h3>

          <div style={{ display: "flex", gap: "8px" }}>
            {/* ➕ ADD FRIENDS PAGE BUTTON */}
            <button
  onClick={() => navigate("/friends")}
  style={{
    position: "relative",
    padding: "8px 12px",
  }}
>
  Add Friends

  {incomingCount > 0 && (
    <span
      style={{
        background: "red",
        color: "white",
        borderRadius: "50%",
        padding: "4px 8px",
        fontSize: "12px",
        marginLeft: "8px",
      }}
    >
      {incomingCount}
    </span>
  )}
</button>

            {/* 🔴 LOGOUT */}
            <button
              onClick={logout}
              style={{
                background: "red",
                color: "white",
                border: "none",
                padding: "6px 12px",
                borderRadius: "5px",
                cursor: "pointer",
                fontSize: "12px",
              }}
            >
              Logout
            </button>
          </div>
        </div>

        {/* 👥 FRIEND LIST */}
        {friendUsers.length === 0 ? (
          <p>No friends yet. Go to Add Friends.</p>
        ) : (
          friendUsers.map((user) => {
            const isOnline = onlineUsers.includes(
              String(user.id)
            );

            return (
              <div
                key={user.id}
                onClick={() => {
                  setSelectedUser(user);
                  fetchMessages(user.id);
                  setIsTyping(false);

                  // Reset unread count
                  setUnreadCounts((prev) => ({
                    ...prev,
                    [String(user.id)]: 0,
                  }));
                }}
                style={{
                  padding: "12px",
                  marginBottom: "10px",
                  cursor: "pointer",
                  borderRadius: "8px",
                  background:
                    selectedUser?.id === user.id
                      ? "#d1e7ff"
                      : "white",
                  display: "flex",
                  justifyContent: "space-between",
                  alignItems: "center",
                  border: "1px solid #ddd",
                }}
              >
                <div style={{ display: "flex", gap: "8px", alignItems: "center" }}>
                  <strong>{user.name}</strong>

                  {/* 🔔 UNREAD BADGE */}
                  {unreadCounts[String(user.id)] > 0 && (
                    <span
                      style={{
                        backgroundColor: "red",
                        color: "white",
                        borderRadius: "50%",
                        padding: "2px 8px",
                        fontSize: "12px",
                        fontWeight: "bold",
                      }}
                    >
                      {unreadCounts[String(user.id)]}
                    </span>
                  )}
                </div>

                {/* 🟢 ONLINE DOT */}
                <span
                  style={{
                    width: "12px",
                    height: "12px",
                    borderRadius: "50%",
                    backgroundColor: isOnline
                      ? "green"
                      : "gray",
                  }}
                />
              </div>
            );
          })
        )}
      </div>

      {/* 🟩 CHAT AREA */}
      <div
        style={{
          flex: 1,
          padding: "20px",
          display: "flex",
          flexDirection: "column",
        }}
      >
        {selectedUser ? (
          <>
            <h2>Chat with {selectedUser.name} 💬</h2>

            {/* ⌨️ Typing Indicator */}
            {isTyping && (
              <p style={{ color: "green" }}>Typing...</p>
            )}

            {/* 💬 MESSAGE BOX */}
            <div
              style={{
                flex: 1,
                border: "1px solid #ccc",
                borderRadius: "10px",
                padding: "15px",
                overflowY: "auto",
                background: "#f9f9f9",
              }}
            >
              {messages.map((msg, index) => (
                <div
                  key={index}
                  style={{
                    textAlign:
                      String(msg.sender_id) ===
                      String(senderId)
                        ? "right"
                        : "left",
                    marginBottom: "10px",
                  }}
                >
                  <div
                    style={{
                      display: "inline-block",
                      padding: "10px",
                      borderRadius: "12px",
                      backgroundColor:
                        String(msg.sender_id) ===
                        String(senderId)
                          ? "#4caf50"
                          : "#e0e0e0",
                      color:
                        String(msg.sender_id) ===
                        String(senderId)
                          ? "white"
                          : "black",
                      maxWidth: "70%",
                    }}
                  >
                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: "6px",
                      }}
                    >
                      <div
  style={{
    display: "flex",
    flexDirection: "column",
    alignItems:
      String(msg.sender_id) === String(senderId)
        ? "flex-end"
        : "flex-start",
  }}
>
  <span>
    {decryptMessage(msg.message)}
  </span>

  {/* 🕒 Timestamp */}
  <small
    style={{
      fontSize: "11px",
      marginTop: "4px",
      opacity: 0.7,
    }}
  >
    {formatTime(msg.created_at)}
  </small>
</div>

                      {/* ✅ WHATSAPP STYLE TICKS */}
                      {String(msg.sender_id) ===
                        String(senderId) && (
                        <small
                          style={{
                            fontSize: "12px",
                            color:
                              msg.status === "seen"
                                ? "blue"
                                : "gray",
                          }}
                        >
                          {msg.status === "sent" && "✓"}
                          {msg.status === "delivered" &&
                            "✓✓"}
                          {msg.status === "seen" && "✓✓"}
                        </small>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>

            {/* ✏️ INPUT */}
            <div
              style={{
                display: "flex",
                marginTop: "15px",
                gap: "10px",
              }}
            >
              <input
                type="text"
                placeholder="Type a message..."
                value={message}
                onChange={handleTyping}
                style={{
                  flex: 1,
                  padding: "12px",
                  borderRadius: "8px",
                  border: "1px solid #ccc",
                }}
                onKeyDown={(e) => {
                  if (e.key === "Enter") sendMessage();
                }}
              />

              <button
                onClick={sendMessage}
                style={{
                  padding: "12px 20px",
                  background: "green",
                  color: "white",
                  border: "none",
                  borderRadius: "8px",
                  cursor: "pointer",
                  fontWeight: "bold",
                }}
              >
                Send
              </button>
            </div>
          </>
        ) : (
          <h2>Select a friend to start chatting 👈</h2>
        )}
      </div>
    </div>
  );
};

export default Chat;